    private Button Action(Node parent,string text,System.Action action,bool accent=false) {var result=Attach(parent,button(text,accent));result.Pressed+=action;return result;}
    private static HBoxContainer Row(Node parent,int separation=7) {var row=Attach(parent,new HBoxContainer());row.AddThemeConstantOverride("separation",separation);return row;}
    private static VBoxContainer Column(Node parent,int separation=4) {var column=Attach(parent,new VBoxContainer());column.AddThemeConstantOverride("separation",separation);return column;}
